recs=[
R(6121396,"ناریل کری ساس میں تلاپیا","کری کئی ایشیائی ممالک میں ایک مقبول ڈش ہے۔ مچھلی کی یہ مزیدار کری کی ترکیب آزمائیں جو بھورے چاول اور سبزیوں کے ساتھ پیش کی جاتی ہے۔","4","1 تلاپیا فلے + 3-4 کھانے کے چمچ ساس + 1/3 کپ پکے ہوئے بھورے چاول",
["1/2 چائے کا چمچ تل کا تیل","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","1/2 چھوٹی پیاز (باریک کٹی ہوئی)","4 چائے کے چمچ تھائی طرز کا ریڈ کری پیسٹ","1 جوا لہسن (باریک کٹا ہوا)","1 کپ بغیر میٹھے کا ناریل دودھ مشروب","1 کھانے کا چمچ قدرتی مونگ پھلی کا مکھن","1 چائے کا چمچ کالی مرچ","4 فلے، ہر ایک تقریباً 5 اونس تلاپیا (بغیر چھلکے کے)","1 1/3 کپ پکے ہوئے بھورے چاول","2 کھانے کے چمچ تازہ ہرا دھنیا (سجاوٹ کے لیے، اگر چاہیں)"],
["اوون کو 375 ڈگری پر پہلے سے گرم کریں۔","اوون میں رکھنے کے قابل ساٹے پین میں درمیانی آنچ پر تل کا تیل اور کافی مقدار میں کوکنگ اسپرے ڈالیں۔ پیاز ڈالیں اور شفاف ہونے تک بھونیں مگر بھورا نہ ہونے دیں، تقریباً 5 منٹ۔","کری پیسٹ، لہسن، ناریل دودھ اور مونگ پھلی کا مکھن ڈال کر ہلائیں اور ہلکی آنچ پر پکائیں جب تک کچھ گاڑھا نہ ہو جائے۔","ہر تلاپیا فلے پر پسی ہوئی کالی مرچ چھڑکیں۔ فلے کو کری میں ڈالیں اور دونوں طرف سے ساس لگا دیں۔","پین کو اوون میں 15-20 منٹ کے لیے رکھیں یا جب تک تلاپیا بس اچھی طرح پک نہ جائے۔","کری کو 1/3 کپ بھورے چاول پر ڈال کر پیش کریں۔ اگر چاہیں تو تازہ ہرے دھنیے سے سجائیں۔"]),
R(6122165,"ساسیج، پھلیوں اور کینوا کا سوپ","یہ پیٹ بھرنے والا سوپ لال پھلیوں اور چاول کی ڈش کا ایک انداز ہے جو سالم اناج کینوا سے بنایا جاتا ہے۔","8","1 کپ",
["1 کھانے کا چمچ زیتون کا تیل","1 درمیانی پیاز (کٹی ہوئی)","1 درمیانی ہری شملہ مرچ (کٹی ہوئی)","1 جوا لہسن (باریک کٹا ہوا)","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","6 اونس کم چکنائی والا اسموکڈ ٹرکی ساسیج (لمبائی میں آدھا کاٹ کر 1 انچ کے ٹکڑوں میں کٹا ہوا)","1 (14.5 اونس) ڈبہ بند کٹے ہوئے ٹماٹر (بغیر اضافی نمک)","1 کپ ڈبہ بند راجما (بغیر اضافی نمک، دھو کر چھانے ہوئے)","16 اونس کم سوڈیم والا چکن شوربہ (بغیر چکنائی)","1/2 چائے کا چمچ کالی مرچ","1/2 چائے کا چمچ خشک تھائم","1 کپ کینوا","2 1/2 کپ گرم پانی"],
["ایک بڑے سوپ پاٹ یا ڈچ اوون میں تیل ڈالیں اور تیز درمیانی آنچ پر گرم کریں۔ پیاز اور ہری شملہ مرچ ڈالیں اور تیز درمیانی آنچ پر 5 منٹ بھونیں۔ لہسن ڈال کر 30 سیکنڈ بھونیں۔","پیاز اور مرچ کا مکسچر برتن سے نکال کر ایک طرف رکھ دیں۔ برتن پر کوکنگ اسپرے کریں۔ ساسیج ڈالیں اور 3-5 منٹ بھورا ہونے تک بھونیں۔","پیاز اور مرچیں دوبارہ برتن میں ڈالیں۔ ٹماٹر، راجما، چکن شوربہ، کالی مرچ، اگر چاہیں تو کیین مرچ اور تھائم ڈالیں۔ ابال آنے تک پکائیں۔ کینوا ڈالیں، آنچ ہلکی کریں اور ڈھانپ دیں۔ 15 منٹ دھیمی آنچ پر پکائیں۔","ڈھکن ہٹا کر پانی ڈالیں۔ مزید 5 منٹ دھیمی آنچ پر پکائیں۔","انتخاب: 1 نشاستہ، 1 غیر نشاستہ دار سبزی، 1 کم چکنائی والا پروٹین، 1/2 چکنائی"]),
R(6123574,"مونگ پھلی کے مکھن، کرین بیری اور اخروٹ والے سیب کے قتلے","سادہ اور مزیدار ساتھ ساتھ چل سکتے ہیں! آپ اس ترکیب کو اپنی پسند کے مطابق بدل سکتے ہیں، سیب کی جگہ ناشپاتی، مونگ پھلی کے مکھن کی جگہ اپنا پسندیدہ میوے کا مکھن، اور کرین بیری کی جگہ کشمش یا خشک چیری استعمال کر کے۔ سب سے اہم بات یہ ہے کہ نیچے دی گئی مقداروں پر قائم رہیں۔","6","2 قتلے",
["2 درمیانے سیب (گٹھلی نکالے ہوئے اور ہر ایک کے 6 قتلے کٹے ہوئے)","4 کھانے کے چمچ کریمی مونگ پھلی کا مکھن","3 کھانے کے چمچ خشک کرین بیری","3 کھانے کے چمچ اخروٹ (کٹے ہوئے)","2 کھانے کے چمچ بغیر میٹھے کے ناریل کے فلیکس"],
["سیب کے 12 قتلے ہموار سطح پر رکھیں۔ ہر قتلے پر 1 چائے کا چمچ مونگ پھلی کا مکھن لگائیں۔","ایک چھوٹے پیالے میں کرین بیری، اخروٹ اور ناریل کے فلیکس ملائیں۔","ہر سیب پر کرین بیری کے مکسچر کا تقریباً 1 کھانے کا چمچ یکساں طور پر چھڑکیں۔"]),
R(6123989,"دلیہ اور پیکن کے پین کیکس","باریک کٹا ہوا جئی کا دلیہ بہت سی ترکیبوں، جیسے ان پین کیکس، میں گیہوں کے آٹے کا آسان سالم اناج متبادل بن سکتا ہے۔ زیادہ فائبر والی ٹاپنگ کے لیے ¾ کپ تازہ بلیو بیریز ڈالیں!","6","1 پین کیک",
["1 کپ جلدی پکنے والا جئی کا دلیہ","1 1/2 چائے کا چمچ بیکنگ پاؤڈر","2 بڑے انڈے","1/3 کپ سکم دودھ","1/2 درمیانا کیلا (میش کیا ہوا، تقریباً 1/3 کپ)","1/2 چائے کا چمچ ونیلا ایکسٹریکٹ","2 کھانے کے چمچ کٹے ہوئے پیکن","1 کھانے کا چمچ کینولا تیل"],
["فوڈ پروسیسر میں جئی کو آٹے جیسی ساخت تک پیس لیں۔ جئی اور بیکنگ پاؤڈر کو ایک چھوٹے پیالے میں ملائیں اور ایک طرف رکھ دیں۔","الگ پیالے میں انڈے، دودھ، میش کیا ہوا کیلا اور ونیلا ملائیں۔ خشک اجزاء میں ڈالیں اور بس مل جانے تک ہلائیں۔ پھر پیکن آہستہ سے ملائیں۔","نان اسٹک اسکلیٹ میں درمیانی آنچ پر تیل گرم کریں۔ ہر پین کیک بنانے کے لیے گرم اسکلیٹ پر 1/4 کپ آمیزہ ڈالیں۔ دونوں طرف ہلکا بھورا ہونے تک پکائیں۔"]),
R(6126102,"بروکلی پنیر کا سوپ","روایتی بروکلی چیڈر سوپ کا کم کیلوری والا ورژن، یہ ترکیب پھر بھی ذائقے سے بھرپور ہے اور مزید سبزیاں کھانے کا ایک بہترین طریقہ ہے۔","8","3/4 کپ",
["1 چائے کا چمچ کینولا یا مکئی کا تیل","1 چھوٹی پیاز (باریک کٹی ہوئی)","2 جوے لہسن (باریک کٹے ہوئے)","1 پاؤنڈ بروکلی کے پھول (کٹے ہوئے (تقریباً 4 کپ))","2 کپ چکن یا سبزی کا شوربہ (بغیر چکنائی، کم سوڈیم)","1/2 چائے کا چمچ رائی کا پاؤڈر","1/4 چائے کا چمچ کالی مرچ","1/8 چائے کا چمچ لال تیز مرچ کی ساس (اختیاری)","1/8 چائے کا چمچ کوشر نمک","2 کپ دودھ (بغیر چکنائی)","1/3 کپ عام استعمال کا میدہ","1/2 کپ بغیر چکنائی کا ہاف اینڈ ہاف","2 اونس چیڈر پنیر (کم چکنائی والا، قتلے یا کدوکش کیا ہوا)","2 کھانے کے چمچ پارمیزان (کدوکش یا پسا ہوا)"],
["ایک بڑے ساس پین میں درمیانی آنچ پر تیل گرم کریں، پین کو گھما کر پیندا چکنا کر لیں۔ پیاز اور لہسن کو 3-4 منٹ پکائیں، یا جب تک پیاز تقریباً نرم نہ ہو جائے، بار بار ہلاتے رہیں۔","بروکلی، شوربہ، رائی، کالی مرچ، تیز مرچ کی ساس اور نمک ڈال کر ہلائیں۔ آنچ تیز درمیانی کریں اور ابال آنے دیں۔ آنچ کم کریں اور 5 منٹ دھیمی آنچ پر پکائیں، یا جب تک بروکلی نرم نہ ہو جائے، وقفے وقفے سے ہلاتے رہیں۔","ایک درمیانے پیالے میں دودھ اور میدہ پھینٹ کر ملائیں۔ سوپ میں ڈال کر ہلائیں۔ 2-3 منٹ دھیمی آنچ پر پکائیں، یا جب تک آمیزہ گاڑھا نہ ہو جائے، وقفے وقفے سے ہلاتے رہیں۔","ہاف اینڈ ہاف، چیڈر اور پارمیزان ڈال کر ہلائیں۔ ہلکی درمیانی آنچ پر 1-2 منٹ پکائیں، یا جب تک پنیر پگھل نہ جائیں، وقفے وقفے سے ہلاتے رہیں۔"]),
R(6127449,"میش کیا ہوا بٹرنٹ اسکواش","خزاں یا سردیوں کی سائیڈ ڈش کے لیے بہترین، ذیابیطس کے لیے موزوں یہ میش کیا ہوا بٹرنٹ اسکواش میش آلو کا مزیدار اور کم کاربوہائیڈریٹ متبادل ہے۔","4","1 کپ",
["1 چھوٹا بٹرنٹ اسکواش (چھلا ہوا اور چوکور کٹا ہوا)","2 جوے لہسن (باریک کٹے ہوئے)","1 کھانے کا چمچ زیتون کا تیل","1/4 چائے کا چمچ نمک","1/2 چائے کا چمچ کالی مرچ"],
["بٹرنٹ اسکواش کے ٹکڑوں کو بھاپ دیں یا ابالیں جب تک کانٹا آسانی سے اندر نہ چلا جائے۔ اگر بھاپ دی ہو تو پکے ہوئے اسکواش کو اسٹیمر باسکٹ سے نکال کر بڑے پیالے میں ڈال دیں۔ اگر ابالا ہو تو بٹرنٹ اسکواش کو چھان کر بڑے پیالے میں ڈالیں۔","باریک کٹا ہوا لہسن، زیتون کا تیل، نمک اور کالی مرچ ڈالیں اور ہموار ہونے تک میش کریں۔"]),
R(6127541,"کروک پاٹ سبزیوں کا سوپ","یہ سوپ سبزی کی ایک بہترین سائیڈ ڈش بناتا ہے۔ اسے بھنے ہوئے چکن یا مچھلی کے ساتھ پیش کریں۔ یہ اچھی طرح فریز ہو جاتا ہے، اس لیے اگر چاہیں تو کچھ حصہ بعد کی تاریخ کے لیے بچا کر رکھ سکتے ہیں۔","6","2 کپ",
["2 ڈبے بغیر اضافی نمک کے کٹے ہوئے ٹماٹر (14 اونس، رس سمیت)","1 پوری بڑی پیاز (کٹی ہوئی)","4 جوے لہسن (باریک کٹے ہوئے)","2 بڑی گاجریں (کٹی ہوئی)","2 ڈنڈیاں اجوائن (کٹی ہوئی)","1 درمیانا پارسنپ (کٹا ہوا)","1 بڑی لال شملہ مرچ (بیج نکالی ہوئی اور کٹی ہوئی)","6 کپ کم سوڈیم والا سبزی کا شوربہ (کم سوڈیم)","3 کپ بند گوبھی (کٹی ہوئی)","1 چائے کا چمچ بغیر نمک کا مسالہ (نمک سے پاک)","1/2 چائے کا چمچ نمک (اختیاری)","1/4 چائے کا چمچ کالی مرچ","1 بڑا میٹھا آلو ((تقریباً 10 اونس)، چھلا ہوا اور کٹا ہوا)"],
["تمام اجزاء کو کروک پاٹ میں ملا کر ہلائیں۔","کروک پاٹ کو ہائی سیٹنگ پر 4-6 گھنٹے کے لیے چلائیں۔","پیش کرنے سے پہلے اچھی طرح ہلائیں اور پارسنپ اور میٹھے آلو کو ہلکا سا میش کر دیں تاکہ سوپ قدرے گاڑھا ہو جائے۔"]),
R(6128101,"بند گوبھی کا سلاد","بند گوبھی آئرش کھانوں کا بنیادی جزو ہے۔ سینٹ پیٹرکس ڈے پر مکمل آئرش لطف کے لیے اس سلاد کو بینگرز اینڈ میش کے ساتھ پیش کریں!","6","1/2 کپ",
["1 (10 اونس) پیکٹ تیار کول سلا مکس","1 کھانے کا چمچ ڈیجون رائی","1 چائے کا چمچ کم یا بغیر کیلوری والا میٹھا (یا 1/2 چائے کا چمچ)","1/2 چائے کا چمچ خشخاش کے بیج","2 کھانے کے چمچ رائس وائن سرکہ","1/3 کپ لائٹ مایونیز"],
["ایک بڑے پیالے میں لائٹ مایونیز، رائس وائن سرکہ، ڈیجون رائی، کم یا بغیر کیلوری والا میٹھا اور خشخاش کے بیج پھینٹ کر ملائیں۔","بند گوبھی کو ڈریسنگ میں آہستہ سے ملائیں اور پیش کرنے سے پہلے 1 گھنٹہ فریج میں رکھیں تاکہ بند گوبھی میرینیٹ ہو جائے۔ (آپ اسے فوراً بھی پیش کر سکتے ہیں لیکن میرینیٹ ہونے دینے پر یہ زیادہ اچھا لگتا ہے)"]),
R(6128345,"ایسپیرگس اور بوک چوئے فریٹاٹا","ناشتے، برنچ، یا رات کے کھانے کے لیے بھی بہترین، ہمارا ایسپیرگس اور بوک چوئے فریٹاٹا ایک ذائقہ دار اور ذیابیطس کا خیال رکھنے والی ڈش ہے جو آپ کے خون میں گلوکوز (بلڈ شوگر) پر کم سے کم اثر ڈالتے ہوئے آپ کے ذائقے کو خوش کرنے کے لیے بنائی گئی ہے۔ یہ فریٹاٹا ایسپیرگس کی تازگی اور بوک چوئے کے ہلکے کرارے پن کو پروٹین سے بھرپور انڈوں کے ساتھ ملاتا ہے، اور ذیابیطس کے مریضوں کے لیے متوازن اور غذائیت بخش کھانا بناتا ہے۔ ضروری غذائی اجزاء سے بھرپور، یہ فریٹاٹا آپ کے ذیابیطس کے لیے موزوں مینو میں ایک مزیدار اضافہ ہے اور ایک تسلی بخش کھانے کا تجربہ فراہم کرتا ہے۔","6","1 ٹکڑا",
["2 کھانے کے چمچ زیتون کا تیل","1 گٹھی ایسپیرگس (نوالے کے سائز کے ٹکڑوں میں کٹی ہوئی)","1 گچھا بے بی بوک چوئے (کٹا ہوا)","1/2 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","2 کپ انڈے کا متبادل","2/3 کپ کم چکنائی والا موزاریلا (کدوکش کیا ہوا)"],
["ایک بڑے اوون میں رکھنے کے قابل اسکلیٹ کو درمیانی آنچ پر پہلے سے گرم کریں۔","اسکلیٹ میں تیل، ایسپیرگس، بوک چوئے، نمک اور کالی مرچ ڈالیں۔ وقفے وقفے سے ہلاتے ہوئے پکائیں جب تک سبزیاں نرم نہ ہو جائیں، 2–3 منٹ۔","انڈے ایک بڑے پیالے میں توڑیں اور پھینٹ کر ملا لیں۔","اوون کو بروئل پر پہلے سے گرم کریں۔","آنچ ہلکی کریں اور انڈے کا آمیزہ اسکلیٹ میں ڈال دیں۔ اسپیچولا سے کناروں کے گرد پکے ہوئے انڈوں کو آہستہ سے اٹھاتے رہیں جب تک کنارے سخت نہ ہو جائیں مگر اوپر کا حصہ ابھی گیلا رہے، 3–4 منٹ۔","فریٹاٹا پر پنیر چھڑکیں۔ اسکلیٹ کو اوون میں رکھیں اور بروئل کریں جب تک اوپر کا حصہ جم نہ جائے اور پنیر پگھل نہ جائے، 1–2 منٹ۔ چھ برابر ٹکڑوں میں کاٹ لیں۔"]),
R(6128588,"گوبھی کے چاول کا سلاد","یہ کم کاربوہائیڈریٹ ڈش تقریباً ہر چیز کے ساتھ اچھی لگتی ہے اور اسے بنانے میں بھی کم وقت لگتا ہے۔","4","1 کپ",
["12 اونس گوبھی کے چاول","1 کپ کھیرا (کٹا ہوا)","1 کپ انگور نما ٹماٹر (آدھے کٹے ہوئے)","2 ڈنڈیاں ہری پیاز (کٹی ہوئی)","3 کھانے کے چمچ کلاماتا زیتون (کٹے ہوئے)","1/4 کپ ریڈ وائن سرکہ","2 کھانے کے چمچ زیتون کا تیل","1/2 کھانے کا چمچ ڈیجون رائی"],
["گوبھی کے چاول کچھ دکانوں سے منجمد خریدے جا سکتے ہیں یا آپ یہ ہدایت اپنا کر خود بنا سکتے ہیں: گوبھی کے پھولوں کو فوڈ پروسیسر میں ڈالیں اور چاول جیسی ساخت تک پیسیں (احتیاط کریں کہ زیادہ نہ پس جائے)۔","ایک بڑے پیالے میں گوبھی کے چاول، کھیرا، ٹماٹر، ہری پیاز اور زیتون ملائیں۔","ایک چھوٹے پیالے میں سرکہ، تیل اور رائی پھینٹ کر ملائیں۔ ڈریسنگ سلاد پر ڈالیں اور ملا لیں۔","ڈریسنگ سلاد پر ڈالیں اور اگر چاہیں تو کم چکنائی والے فیٹا پنیر کے ساتھ پیش کریں۔"]),
R(6129053,"کم خرچ بھرواں شملہ مرچیں","یہ پوری ڈش ایک رات پہلے بنا کر فریج میں رکھ دیں جب تک پیش کرنے کے لیے تیار نہ ہوں۔ بس انہیں اوون یا مائیکرو ویو میں گرم کریں اور پورے خاندان کے لیے رات کا کھانا جلد تیار ہو جائے گا۔ یہ ٹھنڈی کھانے پر بھی مزیدار لگتی ہیں!","6","1 بھری ہوئی شملہ مرچ",
["1 کپ لال یا بھوری مسور کی دال","2 کپ پانی","1 کھانے کا چمچ تازہ ادرک (کدوکش کیا ہوا)","2 جوے لہسن (باریک کٹے ہوئے)","1 چائے کا چمچ ہلدی","1 پاؤنڈ کم چکنائی والا چکن کا قیمہ","1 کھانے کا چمچ تازہ ہرا دھنیا (کٹا ہوا)","1/2 چائے کا چمچ نمک","1/2 چائے کا چمچ کالی مرچ","1/4 چائے کا چمچ کیین مرچ","6 چھوٹی شملہ مرچیں ((کوئی بھی رنگ یا ملے جلے رنگ))","1/2 کپ کم سوڈیم والا چکن شوربہ"],
["اوون کو 350 ڈگری F پر پہلے سے گرم کریں۔","مسور کی دال، پانی، ادرک، لہسن اور ہلدی کو ایک درمیانے ساس پین میں ڈالیں۔ ابال آنے دیں اور پھر آنچ دھیمی کر کے جزوی طور پر ڈھانپ کر 20 منٹ پکائیں۔ ٹھنڈا ہونے کے لیے ایک طرف رکھ دیں۔","جب دال پک رہی ہو، ایک درمیانے پیالے میں چکن کا قیمہ، ہرا دھنیا، نمک، پسی ہوئی کالی مرچ اور کیین مرچ ملائیں اور ایک طرف رکھ دیں۔","شملہ مرچوں کے اوپر کے حصے کاٹ دیں اور بیج والا حصہ نکال دیں (اوپر کے حصے محفوظ رکھیں)۔ مرچوں کے اندر سے پسلیاں اور بیج صاف کریں اور مرچوں کو کٹے ہوئے رخ اوپر کی طرف کر کے بیکنگ ڈش میں قطار میں رکھیں۔ ڈھکن والے حصے ایک طرف رکھ دیں۔ (نوٹ: اگر مرچیں سیدھی نہ کھڑی ہوں تو نیچے سے تھوڑا سا کاٹ دیں تاکہ برابر ہو جائیں اور سیدھی کھڑی رہیں۔ کوشش کریں کہ نیچے سوراخ نہ ہو تاکہ اندر کا آمیزہ باہر نہ گرے)۔","جب دال ٹھنڈی ہو جائے تو اسے چکن کے آمیزے میں ملائیں اور اچھی طرح مکس کریں۔","ہر مرچ کو چکن اور دال کے آمیزے سے بھریں لیکن آمیزے کو زور سے نہ دبائیں۔ بس آہستہ سے اوپر تک بھر دیں۔","چکن اور دال کے آمیزے سے بھری ہر مرچ پر اس کا اوپر کا حصہ واپس رکھیں، پھر چکن کا شوربہ پین کے پیندے میں ڈال دیں۔","1 گھنٹہ بیک کریں یا جب تک چکن کے آمیزے کا اندرونی درجہ حرارت 165 ڈگری نہ ہو جائے۔"]),
R(6129077,"جھینگے اور گرٹس سے بھری شملہ مرچ","کلاسک جھینگے اور گرٹس کا یہ نیا انداز آزمائیں۔ کم کاربوہائیڈریٹ والی یہ ترکیب ذیابیطس کے مریضوں کے لیے بہترین انتخاب ہے اور ہفتے کے دنوں کے آسان رات کے کھانے میں بے شمار ذائقہ بھر دیتی ہے۔","8","1 بھری ہوئی شملہ مرچ کا آدھا حصہ",
["1 کپ اسٹون گراؤنڈ گرٹس","1 کپ چیڈر پنیر (کم چکنائی والا، کدوکش کیا ہوا، تقسیم شدہ)","1/4 چائے کا چمچ کوشر نمک (تقسیم شدہ)","1/4 چائے کا چمچ کالی مرچ (تقسیم شدہ)","4 درمیانی شملہ مرچیں (آدھی کٹی ہوئی، بیج نکالے ہوئے)","1 کھانے کا چمچ زیتون کا تیل","1 درمیانی پیاز (باریک کٹی ہوئی)","2 جوے لہسن","1 کپ چیری ٹماٹر (آدھے کیے ہوئے)","1 پاؤنڈ جھینگے (چھلے ہوئے اور صاف کیے ہوئے)","1 چائے کا چمچ Old Bay مسالہ","1/2 کپ کم سوڈیم والا چکن شوربہ","1 کھانے کا چمچ تازہ اجمودا (کٹا ہوا، سجاوٹ کے لیے)"],
["گرٹس کو پیکٹ پر دی گئی ہدایات کے مطابق پکائیں جب تک وہ کریمی اور ہموار نہ ہو جائیں۔","½ کپ چیڈر پنیر، 1/8 چائے کا چمچ نمک اور 1/8 چائے کا چمچ کالی مرچ آہستہ سے ملائیں۔","اوون کو 375 ڈگری F پر پہلے سے گرم کریں۔","آدھی کٹی ہوئی شملہ مرچوں کو بیکنگ ڈش میں کٹے ہوئے رخ اوپر کر کے رکھیں۔ ڈھانپ کر 40 منٹ بیک کریں۔","ایک بڑے اسکلیٹ میں درمیانی آنچ پر زیتون کا تیل گرم کریں۔ کٹی ہوئی پیاز اور لہسن ڈالیں، نرم ہونے تک بھونیں۔","چیری ٹماٹر، Old Bay مسالہ، باقی کوشر نمک اور کالی مرچ ڈال کر ہلائیں۔ مزید 2 منٹ پکائیں۔","آنچ بند کر دیں اور جھینگے اسکلیٹ میں ڈالیں۔ ملانے کے لیے ہلائیں۔","پکے ہوئے گرٹس کو چمچ سے ہر آدھی شملہ مرچ میں ڈالیں اور چمچ کی پشت سے دبائیں۔ گرٹس کے اوپر جھینگے اور ٹماٹر کا آمیزہ رکھیں۔","ہر بھری ہوئی شملہ مرچ پر باقی کدوکش کیا ہوا چیڈر پنیر چھڑکیں۔","ورق سے ڈھانپ کر بیک کریں جب تک پنیر پگھل نہ جائے، مرچیں نرم نہ ہو جائیں اور بھرائی اچھی طرح پک نہ جائے، تقریباً 20 منٹ۔","پنیر کے بلبلے اٹھنے تک 2-3 منٹ بروئل کریں۔","اوون سے نکالیں اور چند منٹ ٹھنڈا ہونے دیں۔ اگر چاہیں تو تازہ کٹے ہوئے اجمودے سے سجائیں۔"]),
R(6129816,"پالک اور فیٹا آملیٹ","ہری تازہ پالک، کرارے پیاز اور ملائم فیٹا پنیر کا ہلکا سا ذائقہ اس آملیٹ کو ایسا بناتا ہے جو آپ بار بار بنانا چاہیں گے۔","1","1 آملیٹ",
["1/2 کپ انڈے کا متبادل","1/4 چائے کا چمچ کالی مرچ","1 چائے کا چمچ زیتون کا تیل","1/4 کپ لال پیاز (کٹی ہوئی)","1 کپ پالک (کٹی ہوئی)","1 کھانے کا چمچ کم چکنائی والا فیٹا پنیر","1/4 کپ روما (پلم) ٹماٹر (کٹے ہوئے)","1/8 چائے کا چمچ نمک"],
["ایک پیالے میں انڈے کے متبادل میں نمک اور کالی مرچ ڈال کر ملائیں۔","نان اسٹک اسکلیٹ میں درمیانی آنچ پر زیتون کا تیل گرم کریں۔","کٹی ہوئی لال پیاز ڈالیں اور نرم ہونے تک بھونیں۔","کٹی ہوئی پالک اسکلیٹ میں ڈالیں اور مرجھانے تک پکائیں۔","پھینٹے ہوئے انڈے پالک اور پیاز پر ڈال دیں۔","جب انڈے جمنا شروع ہوں تو آدھے آملیٹ پر کٹے ہوئے ٹماٹر اور چورا کیا ہوا فیٹا پنیر چھڑکیں۔","جب انڈے پوری طرح جم جائیں تو اسپیچولا سے آملیٹ کو احتیاط سے آدھا موڑ دیں۔","آملیٹ کو پلیٹ میں پھسلائیں، اگر چاہیں تو تازہ جڑی بوٹیوں سے سجائیں اور پیش کریں۔"]),
R(6130738,"بھنی ہوئی سبزیوں کے ساتھ کری چنے کا اسٹیو","ذیابیطس کے لیے موزوں اس ویگن چنے کے اسٹیو کے ساتھ سبزیوں سے بھرپور ایک آرام دہ پیالے کا لطف اٹھانے کے لیے تیار ہو جائیں۔ ذائقے اور بھنی ہوئی سبزیوں سے بھرپور، یہ آپ کے ذائقے اور آپ کی صحت دونوں کے لیے گرم جوش گلے ملنے جیسا ہے۔","4","2 کپ",
["1 کپ میٹھے آلو (چھلے ہوئے اور کٹے ہوئے، بھنی ہوئی سبزیوں کے لیے)","1 پوری لال شملہ مرچ (کٹی ہوئی، بھنی ہوئی سبزیوں کے لیے)","1 کپ گوبھی کے پھول (بھنی ہوئی سبزیوں کے لیے)","2 چائے کے چمچ زیتون کا تیل (تقسیم شدہ)","1/2 چائے کا چمچ نمک (تقسیم شدہ)","1/2 چائے کا چمچ کالی مرچ (تقسیم شدہ)","1 چھوٹی پیاز (کٹی ہوئی)","2 جوے لہسن (باریک کٹے ہوئے)","2 چائے کے چمچ کری پاؤڈر","1/2 چائے کا چمچ پسی ہوئی ہلدی","14 اونس ڈبہ بند کٹے ہوئے ٹماٹر (بغیر اضافی نمک)","6 اونس لائٹ بغیر میٹھے کا ناریل دودھ","1 کپ کم سوڈیم والا سبزی کا شوربہ","7 اونس ڈبہ بند چنے (دھو کر چھانے ہوئے)","1 گٹھی تازہ ہرا دھنیا (کٹا ہوا، سجاوٹ کے لیے)"],
["اوون کو 400 ڈگری F پر پہلے سے گرم کریں۔ بیکنگ ٹرے پر پارچمنٹ پیپر بچھا دیں۔","ایک بڑے پیالے میں میٹھے آلو، لال شملہ مرچ اور گوبھی کے پھولوں کو 1/8 چائے کا چمچ نمک، 1/4 چائے کا چمچ کالی مرچ اور 1 چائے کا چمچ زیتون کے تیل کے ساتھ ملائیں۔","سبزیوں کو تیار کی ہوئی بیکنگ ٹرے پر ایک تہہ میں پھیلا دیں۔ پہلے سے گرم اوون میں 20–25 منٹ بھونیں جب تک نرم اور ہلکی کیرامیلائزڈ نہ ہو جائیں۔","ایک بڑے برتن یا ڈچ اوون میں درمیانی آنچ پر باقی زیتون کا تیل گرم کریں۔ کٹی ہوئی پیاز اور باریک کٹا ہوا لہسن ڈالیں اور خوشبو آنے اور شفاف ہونے تک بھونیں۔","کری پاؤڈر، ہلدی، 1/4 چائے کا چمچ نمک اور 1/4 چائے کا چمچ کالی مرچ برتن میں ڈالیں۔ اچھی طرح ہلائیں تاکہ پیاز اور لہسن پر مسالے لگ جائیں۔","کٹے ہوئے ٹماٹر (رس سمیت)، ناریل دودھ اور سبزی کا شوربہ ڈالیں۔ ملانے کے لیے ہلائیں۔ دھلے ہوئے چنے برتن میں ڈالیں اور سب کچھ ملا کر ہلائیں۔ آمیزے کو ابال آنے دیں۔","آنچ ہلکی کر دیں اور اسٹیو کو بغیر ڈھانپے تقریباً 15–20 منٹ دھیمی آنچ پر پکنے دیں تاکہ ذائقے آپس میں مل جائیں۔ وقفے وقفے سے ہلاتے رہیں۔","بھنی ہوئی سبزیاں اوون سے نکالیں اور برتن میں ڈال دیں۔ انہیں اسٹیو میں ملانے کے لیے آہستہ سے ہلائیں۔ کری چنے کا اسٹیو پیالوں میں تازہ ہرے دھنیے سے سجا کر پیش کریں۔"]),
R(6131183,"ایڈامامے اور پاستا فیٹا کے ساتھ","اس منفرد پاستا ڈش کو ہلکی ڈریسنگ والے سبزے کے ساتھ پیش کریں۔ یہ ایک بہترین لنچ بھی ہے جو آپ دفتر لے جا سکتے ہیں۔","6","1 کپ",
["4 اونس بغیر پکا ہوا سالم اناج کا پین یا روٹینی پاستا","8 اونس تازہ یا منجمد چھلے ہوئے ایڈامامے","1 1/2 کپ انگور نما ٹماٹر (چار حصوں میں کٹے ہوئے)","16 پورے کلاماتا زیتون (گٹھلی نکالے ہوئے، موٹے کٹے ہوئے)","2 کھانے کے چمچ کٹے ہوئے تازہ تلسی کے پتے، یا 2 چائے کے چمچ خشک تلسی کے پتے","1/2 چائے کا چمچ روزمیری کے پتے (چورا کیے ہوئے (اختیاری))","1 جوا لہسن (باریک کٹا ہوا)","1/8 چائے کا چمچ کٹی ہوئی لال مرچ کے فلیکس (اختیاری)","1 درمیانا لیموں (رس نکالا ہوا)","2 اونس فیٹا پنیر (کم چکنائی والا، چورا کیا ہوا)"],
["پاستا کو پیکٹ پر دی گئی ہدایات کے مطابق پکائیں، نمک یا چکنائی ڈالے بغیر، اور پکانے کے آخری 2 منٹ میں ایڈامامے ڈال دیں۔","ایک چھوٹے پیالے میں ٹماٹر، زیتون، تلسی، روزمیری (اختیاری)، لہسن اور مرچ کے فلیکس ملائیں۔ ملانے کے لیے اچھالیں اور ایک طرف رکھ دیں۔","پاستا اور ایڈامامے کو چھلنی میں چھان لیں، پیش کرنے والی تھالی یا پاستا کے پیالے میں رکھیں، سب پر لیموں نچوڑیں، اوپر فیٹا ڈالیں اور ٹماٹر کا آمیزہ بیچ میں ڈھیر کر دیں۔"]),
]
save(2,recs)
